function filePrint(title:string,rows:string[][]){const page=window.open("","_blank");if(!page){window.alert("Allow pop-ups to print.");return}const escaped=(x:string)=>x.replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]||c));page.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${escaped(title)}</title><style>body{font:11px Arial,sans-serif;padding:14px;color:#243044}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d6dce6;padding:5px;overflow-wrap:anywhere}th{background:#eef3f7}h2{font-size:18px}@page{size:landscape;margin:12mm}</style></head><body><h2>${escaped(title)} — working spreadsheet</h2><p>Preview / working copy only. Not an approved payroll modification or official government report.</p><table><thead><tr>${rows[0].map(x=>`<th>${escaped(x)}</th>`).join("")}</tr></thead><tbody>${rows.slice(1).map(row=>`<tr>${row.map(x=>`<td>${escaped(x)}</td>`).join("")}</tr>`).join("")}</tbody></table><script>window.onload=()=>window.print()</script></body></html>`);page.document.close()}

