 useEffect(()=>{const unsubscribe=subscribeSheetChanges(()=>setState(readSheetState()));const t=window.setInterval(()=>{setTick(Date.now());setState(readSheetState())},15000);return ()=>{unsubscribe();window.clearInterval(t)}},[]);
 useEffect(()=>{const start=new URLSearchParams(window.location.search).get("sheet");if(start&&/^[a-z0-9-]+$/.test(start)&&start!=="working-sheet")setSheetId(workbookId==="payroll"?`${currentBatchId||"unselected"}--${start}`:start)},[workbookId,currentBatchId]);
 useEffect(()=>{const uploadId=new URLSearchParams(window.location.search).get("driveFile");if(!uploadId||!/^[a-zA-Z0-9-]{1,100}$/.test(uploadId))return;
  let alive=true;(async()=>{const meta=readDrive().uploads.find(x=>x.id===uploadId);if(!meta||!/\.xlsx$/i.test(meta.name))throw Error("This Drive item is not an XLSX workbook.");const blob=await getDriveBlob(uploadId);if(!blob)throw Error("Drive file contents are unavailable in this browser.");const tabs=await readExcelFile(new File([blob],meta.name,{type:meta.mime}));if(alive){setImportTabs(tabs);setImportTabIndex(0);setSheetId("working-sheet");setNotice(`Loaded ${meta.name} from Drive. Preview only—request approval before importing.`)}})().catch(err=>{if(alive)setError(err instanceof Error?err.message:"Drive workbook cannot be opened.")});return()=>{alive=false}
 },[]);

 const batchChoices=useMemo(()=>payrollBatchOverviews(normalizePayrollConfig(data.payrollConfig),data.payrollReleases,data.people).filter(b=>branch==="All Shops"||b.branch===branch),[data,branch]);
 const sheets=useMemo<Sheet[]>(()=>[
  ...buildWorkbookSheets(data,branch,workbookId,currentBatchId),
  ...(workbookId==="working"?state.customSheets.map(s=>({id:s.id,title:s.title,note:"Approved working sheet; never edits HRMS source records.",columns:[],rows:[]})):[])
 ],[data,branch,workbookId,currentBatchId,state.customSheets]);
