 const copySelection=async()=>{try{if(rangeSize(activeRange)>2000)throw Error("Select at most 2,000 cells to copy.");const text=Array.from({length:activeRange.bottom-activeRange.top+1},(_,r)=>Array.from({length:activeRange.right-activeRange.left+1},(_,c)=>raw(cellRef({row:activeRange.top+r,col:activeRange.left+c}))).join("\t")).join("\n");await navigator.clipboard.writeText(text);copiedRange.current={text,start:{row:activeRange.top,col:activeRange.left}};setNotice(`Copied ${activeRangeAddress}.`);setError("")}catch(err){setError(err instanceof Error?err.message:"Clipboard is unavailable.")}};
