 const chooseExcel=()=>excelFile.current?.click();
 const loadExcel=async(file?:File)=>{if(!file)return;setExcelBusy(true);setError("");setNotice("");try{const tabs=await readExcelFile(file);setImportTabs(tabs);setImportTabIndex(0);setNotice(`Loaded ${tabs.length} Excel tab(s). Preview and choose a destination below.`)}catch(err){setImportTabs(null);setError(err instanceof Error?err.message:"Cannot open this Excel file.")}finally{setExcelBusy(false)}};
