  const targets=all?sheets:[sheet];const projected=targets.map(t=>{const work=state.sheets[t.id],rowsBase=work?.snapshot?[work.snapshot.columns,...work.snapshot.rows]:[t.columns.map(c=>c.label),...t.rows.map(r=>r.map(v=>String(v??"")))];return {name:t.title,rows:rowsBase,overlay:work?.cells,formats:work?.formats}});
